// any method can block, even deep inside an old library
void settle(Payment p) throws InterruptedException {
    Auth auth = issuer.authorize(p);       // blocking socket read: unmounts here
    Thread.sleep(Duration.ofMillis(30));   // unmounts here too
    ledger.record(p, auth);                // plain JDBC over a socket: unmounts
}

// run it on a virtual thread; nothing in settle() knows
Thread.ofVirtual().name("settle-", 0).start(() -> {
    try { settle(payment); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
});

