        now = sleeping.peek().wakeAt();
        while (!sleeping.isEmpty() && sleeping.peek().wakeAt() <= now) {
            ready.addLast(sleeping.poll().fiber()); // JDK: the timer unparks, thread is resubmitted
        }
    }
    Fiber f = ready.pollFirst();                    // JDK: a carrier takes the next task (FIFO)
    mounts++;
    Step step = f.resume();                         // JDK: mount, Continuation.run()
    if (step instanceof Step.Sleep s) {             // JDK: Continuation.yield() at sleep, unmount
        sleeping.add(new Parked(now + s.millis(), seq++, f));
    }
}
